const r=()=>S.mode==='LIVE'?S.snapshot?.account:M.runtime(S.snapshot,S.mode);
const ai=()=>M.analysis(S.snapshot,S.mode);
const snapshotCacheKey=()=>{const id=String(window.Telegram?.WebApp?.initDataUnsafe?.user?.id||'');return id?`wh_product_snapshot_v2:${id}`:null;};
function positionCacheKey(p){return JSON.stringify([p?.instrument?.network,p?.instrument?.dex||'',p?.instrument?.symbol,p?.side,p?.order_ids||[]]);}
function homeMarketKey(p){const scope=S.snapshot?.scope||{};const i=p?.instrument||{};return JSON.stringify([scope.tenant,scope.account,scope.network||i.network,p?.mode||S.mode,i.network,i.dex||'',i.symbol,S.interval,S.interval==='1d'?720:168]);}
function rememberHomeMarket(key,patch){const prior=homeMarketCache.get(key)||{candles:[],mark:null,candlesAt:0,markAt:0};const next={...prior,...patch};homeMarketCache.set(key,next);while(homeMarketCache.size>8)homeMarketCache.delete(homeMarketCache.keys().next().value);return next;}
function mergePortfolio(previous,next){
 if(!next)return previous;
 if(!previous)return next;
 const old=new Map((previous.positions||[]).map(p=>[positionCacheKey(p),p]));
 const positions=(next.positions||[]).map(p=>{
  const prior=old.get(positionCacheKey(p));
  if(!prior)return p;
  const keep=(key)=>N(p[key])!==null?p[key]:prior[key];
  return {...p,current_price:keep('current_price')??keep('mark_price'),mark_price:keep('mark_price'),mark_timestamp:keep('mark_timestamp'),pnl:keep('pnl'),pnl_kind:p.pnl_kind||prior.pnl_kind};
 });
 return {...next,positions};
}
function mergeSnapshot(next){
 const previous=S.snapshot;
 if(!previous||M.scopeKey(previous.scope)!==M.scopeKey(next.scope))return next;
 const merged={...next};
 if(!next.account&&previous.account)merged.account=previous.account;
 else if(next.account?.portfolio||previous.account?.portfolio)merged.account={...previous.account,...next.account,portfolio:mergePortfolio(previous.account?.portfolio,next.account?.portfolio)};
 if(!Array.isArray(next.runtimes)&&Array.isArray(previous.runtimes))merged.runtimes=previous.runtimes;
 return merged;
}
function persistSnapshot(s){const key=snapshotCacheKey();if(!key)return;try{localStorage.setItem(key,JSON.stringify({saved_ms:Date.now(),snapshot:s}));}catch{} }
function restoreSnapshot(){const key=snapshotCacheKey();if(!key)return null;try{const value=JSON.parse(localStorage.getItem(key)||'null');if(!value?.snapshot||Date.now()-Number(value.saved_ms||0)>86400000)return null;const user=String(window.Telegram?.WebApp?.initDataUnsafe?.user?.id||'');if(!user||String(value.snapshot.scope?.tenant)!==user)return null;return value;}catch{return null;}}
function freshness(at=null){const stamp=N(at)??S.snapshotSavedAt;if(!stamp)return '';const age=Math.max(0,Date.now()-stamp),seconds=Math.floor(age/1000);return `<small class="freshness ${S.snapshotCached||seconds>30?'stale':'live'}">${esc(S.snapshotCached&&!at?t('КЭШ · обновляем','CACHE · revalidating'):seconds>30?t('УСТАРЕЛО','STALE')+' · '+seconds+'с':seconds>1?seconds+'с':t('LIVE','LIVE'))}</small>`;}
const liveOpenPositions=()=>M.positions(S.snapshot,'LIVE').filter(M.isOpen);
const allPositions=()=>[...M.positions(S.snapshot,'LIVE'),...(S.snapshot?.runtimes||[]).flatMap(x=>M.positions(S.snapshot,x.mode))];
const positionRows=(rows)=>rows.length?`<div class="list">${rows.map(p=>`<button class="position" data-key="${esc(p.id)}" data-position="${esc(p.id)}"><span class="token">${esc(p.instrument?.symbol?.slice(0,1)||'◇')}</span><span class="grow"><strong>${esc(p.instrument?.symbol||'—')} · ${esc(L(p.side))}</strong><small>${esc(L(p.origin||'UNKNOWN'))} · ${esc(p.mode)}</small><small>${esc(t('Вход','Entry'))}: ${cash(p.entry)} · ${esc(t('Цена','Price'))}: ${cash(p.current_price)}</small><small>${esc(t('Маржа','Margin'))}: ${cash(p.margin)} · ${esc(t('Плечо','Leverage'))}: ${esc(num(p.leverage,0)+'×')} · ${esc(t('Объём','Size'))}: ${secret(num(p.size,6))}</small></span><span class="right"><b class="${N(p.pnl)!==null&&p.pnl<0?'bad':'good'}">${cash(p.pnl)}</b><small>${esc(p.outcome?.return_pct!=null?num(p.outcome.return_pct)+'%':N(p.pnl)!==null&&N(p.margin)>0?num(p.pnl/p.margin*100)+'%':'—')} ›</small>${p.unresolved||['UNKNOWN','PARTIAL','RECONCILIATION_REQUIRED'].includes(p.state)?badge(p.state):''}</span></button>`).join('')}</div>`:empty(t('Нет открытых позиций','No open positions'));
const textEvidence=value=>{if(Array.isArray(value))return value.map(textEvidence).join(' · ');if(value&&typeof value==='object')return Object.entries(value).filter(([k])=>!['scope','account','tenant'].includes(k)).slice(0,12).map(([k,v])=>`${L(k)}: ${textEvidence(v)}`).join(' · ');return L(value??'—');};
const evidence=v=>`<div class="evidence sensitive">${esc(textEvidence(v))}</div>`;
function consensus(c=ai()?.consensus){const stale=c===ai()?.consensus&&ai()?.consensus_health?.decision_fresh===false;if(!c||stale)return `<div class="consensus-value">${esc(ai()?.consensus_health?.status==='READY'?'READY':t('ОЖИДАНИЕ','WAITING'))}</div><p class="footer-note">${esc(t('Ожидаем новое событие лидера','Waiting for a new leader event'))}</p>${stale?`<details><summary>${esc(t('Последнее решение · архив','Last decision · historical'))}</summary>${evidence(c)}</details>`:''}`;return c?`<div class="eyebrow">${esc(dt(c.created_ms))}</div><div class="consensus-value">${esc(L(c.decision))}</div><div class="row"><span>${esc(t('Уверенность','Confidence'))}</span><b>${pc(c.confidence)}</b></div>${c.blockers?.length?`<p class="footer-note">${esc(t('Недостаточно подтверждений для исполнения','Insufficient execution evidence'))}</p>`:''}<details><summary>${esc(t('Причины и детали','Reasons & details'))}</summary>${evidence(c.blockers)}${evidence({[t('За','Support')]:c.supporting,[t('Против','Opposition')]:c.opposing,[t('Версия','Version')]:c.policy_id})}<p class="footer-note">${esc(t('Уверенность — не вероятность прибыли.','Confidence is not a profit probability.'))}</p></details>`:empty(t('Ожидаем событие лидера','Waiting for a leader event'));}
function sessionCard(){const run=r(),s=run?.session;if(!s)return '';const alive=run.worker?.heartbeat_ms&&Date.now()-run.worker.heartbeat_ms<90000;return card('PAPER SESSION',`<div class="row">${badge(alive?'ACTIVE':'DEGRADED')}<small>${esc(s.allowed_instrument)} · ${esc(t('Политика фиксирована','Fixed policy'))}</small></div><div class="metrics">${metric(t('Стартовый капитал','Starting capital'),cash(s.virtual_starting_capital))}${metric(t('Прошло','Elapsed'),num(Math.max(0,Date.now()-s.start_ms)/3600000,1)+' '+t('ч','h'))}${metric(t('Сделки','Trades'),num(run.analytics?.trade_count,0))}${metric('PnL',cash(run.analytics?.net_pnl))}</div><details><summary>${esc(t('Сессия и сроки','Session & dates'))}</summary><small class="session-id">${esc(s.session_id)}</small><small>${esc(dt(s.start_ms))} → ${esc(dt(s.evaluation_end_ms))}</small></details>`,'paper-session');}
function chartBlock(id){return `${tabs(['24H','7D','30D','ALL'],S.period,'period')}<div class="chart-wrap"><canvas class="chart financial-chart" data-key="${id}" id="${id}" role="img" aria-label="${esc(t('Реализованный PnL','Realized PnL'))}"></canvas><div class="chart-tooltip" id="${id}-tip"></div></div><small>${esc(t('Накопленный реализованный PnL · последние 100 исходов','Cumulative realized PnL · latest 100 outcomes'))}</small>`;}
function fold(title,body,key){return `<details class="compact-detail" data-key="${esc(key)}"><summary>${esc(title)}</summary>${body}</details>`;}
function tradingStatus(){const run=r(),d=run?.latest_decision,event=d?.event,c=d?.consensus,unresolved=(run?.execution?.reconciliation_backlog||0)>0;const reasons={NO_FOLLOWER_POSITION:t('У нас нет позиции для этого закрытия или сокращения','No follower position to close or reduce'),SCOPE_MISMATCH:t('Инструмент вне разрешённого списка этой сессии','Instrument is outside this session’s allowed scope'),STRONG_DISAGREEMENT:t('Агенты расходятся в направлении','Agents disagree on direction'),CONSENSUS_BELOW_THRESHOLD:t('Недостаточно подтверждений для входа','Insufficient confirmation for entry')};const reason=unresolved?t('Ожидаем сверку предыдущего исполнения. Повтора не будет.','Waiting for execution reconciliation. No retry.'):reasons[d?.reason]||(c?.blockers||[]).map(k=>reasons[k]).filter(Boolean).join(' · ')||(d?t('Последнее событие обработано — подробности ниже','Latest event processed — details below'):t('Ждём подходящий сигнал. Анализ сам по себе не открывает позицию.','Waiting for an eligible signal. Analysis alone does not open a position.'));return card(t('ИСПОЛНЕНИЕ СТРАТЕГИИ','STRATEGY EXECUTION'),`<div class="row"><b>${esc(S.mode)}</b><small>${esc(run?.allowed_instrument?.symbol||run?.session?.allowed_instrument||'—')}</small></div><p class="footer-note">${esc(reason)}</p>${event?`<small>${esc(event.instrument?.symbol)} · ${esc(L(event.action))} · ${esc(dt(event.exchange_ms))}</small>`:''}<details><summary>${esc(t('Последнее решение','Latest decision'))}</summary>${evidence(d||t('Пока нет решения','No decision yet'))}</details>`,'trading-status');}
function activity(limit=40){const rows=S.events.map(e=>({event:e,view:M.activityEvent(e)})).filter(x=>S.page!=='activity'||S.activityFilter==='ALL'||x.view.category===S.activityFilter).slice(0,limit);return rows.length?`<div class="activity-timeline">${rows.map(({event:e,view:v})=>`<article class="activity-event" data-category="${v.category}" data-key="event-${esc(e.id)}"><span class="timeline-node" aria-hidden="true"></span><div class="activity-time"><time>${esc(N(e.timestamp)===null?'—':new Date(e.timestamp).toLocaleTimeString(S.lang==='en'?'en-GB':'ru-RU',{hour:'2-digit',minute:'2-digit'}))}</time><small>${esc(L(v.category))}</small></div><div class="grow"><strong>${esc(L(v.title))}</strong><div class="activity-summary">${esc([v.symbol,L(v.action),L(v.side),v.confidence!==null?num(v.confidence*100,0)+'%':''].filter(Boolean).join(' · '))}</div>${v.wallet?`<small class="sensitive">${wallet(v.wallet)}</small>`:''}${v.mode?`<small class="mode-label">${esc(v.mode)}</small>`:''}<details><summary>${esc(t('Технические детали','Technical details'))}</summary><pre class="sensitive">${esc(JSON.stringify(v.technical,null,2))}</pre></details></div></article>`).join('')}</div>`:empty(t('В этой категории пока нет событий','No events in this category yet'));}
function activityPage(){return card(L('activity'),`<div class="activity-filters" role="group" aria-label="${esc(t('Категории событий','Activity categories'))}">${['ALL','TRADING','AI','LEADERS','RISK','SYSTEM'].map(k=>`<button data-activity-filter="${k}" aria-pressed="${S.activityFilter===k}">${esc(L(k))}</button>`).join('')}</div>${activity(200)}`,'all-events');}
const notificationLabels={OPEN:['Открытие позиции','Position open'],ADD:['Увеличение позиции','Position add'],REDUCE:['Сокращение позиции','Position reduce'],REVERSE:['Разворот позиции','Position reverse'],CLOSE:['Закрытие позиции','Position close'],CRITICAL:['Критические ошибки','Critical errors'],LIVE_CONFIRM:['Подтверждения LIVE','LIVE confirmation']};
function notificationSettings(){return card(t('УВЕДОМЛЕНИЯ TELEGRAM','TELEGRAM NOTIFICATIONS'),S.notificationPrefs?Object.entries(notificationLabels).map(([key,label])=>`<div class="state-row"><span>${esc(t(...label))}</span><button role="switch" data-notification="${key}" aria-checked="${S.notificationPrefs[key]}" aria-label="${esc(t(...label))}" ${S.prefsBusy?'disabled':''}>${esc(S.notificationPrefs[key]?t('Вкл','On'):t('Выкл','Off'))}</button></div>`).join('')+`<p class="footer-note">${esc(t('Только ваши позиции и важные ошибки. Аналитика — в Событиях. SHADOW не отправляет сообщения о сделках.','Only your positions and critical errors. Research stays in Activity. SHADOW sends no trade messages.'))}</p>`:`<button data-load-notifications>${esc(t('Загрузить настройки','Load preferences'))}</button>`,'notification-settings');}
function homePositionPanel(open){const selected=open.find(p=>p.id===S.homePositionId)||open[0],ids=open.slice(0,8);if(selected)S.homePositionId=selected.id;const chips=ids.length>1?`<div class="position-chips" role="group" aria-label="${esc(t('Позиции','Positions'))}">${ids.map(p=>`<button class="${p.id===selected.id?'selected':''}" data-home-position="${esc(p.id)}">${esc(p.instrument?.symbol||'—')}</button>`).join('')}</div>`:'';if(!selected)return card(t('ПОЗИЦИЯ И РЫНОК','POSITION & MARKET'),`${empty(t('Нет открытых позиций. PAPER ожидает сигнал.','No open positions. PAPER is waiting for a signal.'))}`,'home-position');const mark=N(S.homeMark?.price)!==null?S.homeMark.price:selected.current_price;const entry=N(selected.entry_price??selected.entry),size=N(selected.size),livePnl=N(mark)!==null&&entry!==null&&size!==null&&['LONG','SHORT'].includes(selected.side)?(mark-entry)*size*(selected.side==='LONG'?1:-1):selected.pnl;return card(`${esc(selected.instrument?.symbol||'—')} · ${esc(L(selected.side))}`,`${chips}<button class="position home-position-summary" data-position="${esc(selected.id)}"><span class="token">${esc(selected.instrument?.symbol?.slice(0,1)||'◇')}</span><span class="grow"><strong>${esc(t('Открытая позиция','Open position'))}</strong><small>${esc(L(selected.origin||'UNKNOWN'))} · ${esc(selected.mode)}</small></span><span class="right"><b class="${N(livePnl)!==null&&livePnl<0?'bad':'good'}">${cash(livePnl)}</b><small>${esc(t('Цена','Price'))}: ${cash(mark)}</small></span></button><div class="home-position-chart"><canvas class="chart candle" id="home-position-chart" data-key="home-position-canvas" role="img" aria-label="${esc(t('График открытой позиции','Open position chart'))}"></canvas><div class="chart-tooltip" id="home-position-chart-tip"></div></div><div class="metrics compact-financials">${metric(t('Вход','Entry'),cash(selected.entry))}${metric(t('Текущая цена','Current price'),cash(mark))}${metric(t('Маржа','Margin'),cash(selected.margin))}${metric(t('Плечо','Leverage'),esc(num(selected.leverage,0)+'×'))}${metric(t('Размер','Size'),secret(num(selected.size,6)))}${metric(t('ROE %','ROE %'),N(livePnl)!==null&&N(selected.margin)>0?num(livePnl/selected.margin*100)+'%':'—')}</div>${freshness(S.homeMark?.time||selected.mark_timestamp)}`,'home-position','hero');}
function home(){const run=r(),a=run?.analytics||{},modeOpen=M.positions(S.snapshot,S.mode).filter(M.isOpen),liveOpen=liveOpenPositions(),showLive=liveOpen.length>0&&S.snapshot?.account?.portfolio?.completeness==='COMPLETE',open=showLive?liveOpen:modeOpen,known=showLive||S.mode==='LIVE'?((showLive?S.snapshot.account?.portfolio:run?.portfolio)?.completeness==='COMPLETE'):Array.isArray(run?.episodes),portfolio=showLive?S.snapshot.account.portfolio:run?.portfolio,manual=S.snapshot.manual_copy||{};return `<div class="grid home-grid"><div class="home-main">${card(showLive?t('РЕАЛЬНЫЙ СЧЁТ','LIVE ACCOUNT'):S.mode==='SHADOW'?t('ГИПОТЕТИЧЕСКИЙ КАПИТАЛ','HYPOTHETICAL CAPITAL'):t('БАЛАНС СТРАТЕГИИ','STRATEGY BALANCE'),`<div class="balance">${cash(portfolio?.equity)}</div><div class="metrics">${metric(t('Реализованный PnL','Realized PnL'),cash(a.net_pnl))}${metric(t('Доступный капитал','Available allocation'),cash(run?.allocation?.available))}${metric(t('Сеть','Network'),esc(S.snapshot.scope.network))}</div><p class="session">${esc(showLive?'LIVE':S.mode)} · ${esc(L(manual.ui_state||manual.status))} Manual Copy · ${freshness(portfolio?.received_ms)}</p>`,'hero','hero')}${known?homePositionPanel(open):card(t('ПОЗИЦИЯ И РЫНОК','POSITION & MARKET'),empty(),'home-position')}${card(t('СТАТИСТИКА','STATISTICS'),`<div class="metrics">${metric(t('Сделки','Trades'),num(a.trade_count,0))}${metric(t('Открыто','Open'),num(known?open.length:null,0))}${metric(t('Ожидание','Expectancy'),cash(a.expectancy))}</div>${(a.sample_size||0)<10?`<p class="footer-note">${esc(t('Малая выборка. Результаты ещё не статистически значимы.','Small sample. Results are not yet statistically meaningful.'))}</p>`:`<div class="metrics">${metric(t('Доля побед','Win rate'),pc(a.win_rate))}${metric('Profit Factor',num(a.profit_factor))}</div>`}`,'kpi')}${card(t('РЕЗУЛЬТАТЫ','PERFORMANCE'),chartBlock('home-chart')+`<button class="link" data-nav="analytics">${esc(t('Подробная аналитика →','Detailed analytics →'))}</button>`,'performance')}</div><div class="home-side">${fold(t('PAPER-сессия','PAPER session'),sessionCard(),'home-session')}${tradingStatus()}${card(t('ПУБЛИЧНЫЙ АНАЛИЗ · НЕ ПРИКАЗ','PUBLIC ANALYSIS · NOT AN ORDER'),consensus()+`<button class="link" data-nav="agents">${esc(t('AI и лидеры →','AI & leaders →'))}</button>`,'consensus')}${card(t('СОБЫТИЯ','ACTIVITY'),activity(3)+`<button data-nav="activity">${esc(t('Все события','All activity'))}</button>`,'activity')}</div></div>`;}
function positions(){if(S.mode==='LIVE'?S.snapshot.account?.portfolio?.completeness!=='COMPLETE':!Array.isArray(r()?.episodes))return empty();const all=M.positions(S.snapshot,S.mode).filter(M.isOpen),sources=['ALL',...new Set(all.map(p=>p.origin))];if(!sources.includes(S.filter))S.filter='ALL';const rows=S.filter==='ALL'?all:all.filter(p=>p.origin===S.filter);return (sources.length>2?tabs(sources,S.filter,'filter'):'')+richPositions(rows);}
function pulse(element,name){if(!element||!S.motion)return;element.classList.remove(name);requestAnimationFrame(()=>element.classList.add(name));setTimeout(()=>element.classList.remove(name),1400);}
function richPositions(rows){return rows.length?`<div class="list">${rows.map(p=>`<button class="position position-rich" data-key="${esc(p.id)}" data-position="${esc(p.id)}"><span class="row"><span class="grow"><strong>${esc(p.instrument?.symbol)} · ${esc(L(p.side))}</strong><small>${esc(L(p.origin||'UNKNOWN'))} · ${esc(p.mode)}</small></span><span class="right">${cash(p.pnl)} ${badge(p.state)}</span></span><span class="metrics">${metric(t('Вход','Entry'),cash(p.entry))}${metric(t('Цена','Price'),cash(p.current_price))}${metric(t('Маржа','Margin'),cash(p.margin))}${metric(t('Номинал','Notional'),cash(p.notional))}${metric(t('Плечо','Leverage'),num(p.leverage,0)+'×')}${metric(t('Объём','Size'),secret(num(p.size,6)))}</span></button>`).join('')}</div>`:empty(t('Нет открытых позиций','No open positions'));}
function leaderRows(){return (S.snapshot.discovery?.leaders||[]).map((l,i)=>{const w=leaderWindow(l),score=l.analysis?.score;return `<button class="leader-row" data-leader="${esc(l.wallet)}" data-key="leader-${esc(l.wallet)}"><span class="token">${i+1}</span><span class="grow"><strong class="sensitive">${esc(l.wallet.slice(0,6)+'…'+l.wallet.slice(-4))}</strong><small>${esc(L(l.status))}</small></span><span class="right"><b class="paper">${num(N(score?.score)!==null?score.score*100:null,0)}</b><small>LeaderScore</small></span><span class="rank-extra">${money(w?.net_pnl)}<small> PnL</small></span><span class="rank-extra">${num(w?.profit_factor)} PF</span></button>`;}).join('')||empty(t('Пока нет квалифицированных лидеров','No qualified leaders yet'));}
function leaderWindow(l){const ws=l?.analysis?.windows;return Array.isArray(ws)?ws.find(w=>String(w.days)===S.window):ws?.[S.window]||ws?.[S.window+'d'];}
function leaders(){const d=S.snapshot.discovery||{},c=d.counts||{};return `<div class="grid">${card(t('ПОИСК ЛИДЕРОВ','WALLET DISCOVERY'),`${d.worker_active&&d.status==='DEGRADED'?badge('ACTIVE')+' · ':''}${badge(d.status)}${d.worker_active?` <small>${esc(t('Поиск активен','Discovery active'))}</small>`:''}<div class="metrics">${Object.entries(c).slice(0,6).map(([k,v])=>metric(L(k),num(v,0))).join('')}</div><details><summary>${esc(t('Охват и свежесть','Coverage & freshness'))}</summary>${evidence(d.coverage?.observed_instruments)}${evidence(d.reasons)}<small>${esc(t('Только наблюдаемые рынки, не все кошельки Hyperliquid.','Observed markets only, not every Hyperliquid wallet.'))} ${esc(dt(d.last_success_ms))}</small></details>`,'discovery')}${card(t('РЕЙТИНГ ЛИДЕРОВ','LEADER RANKING'),`<div class="list">${leaderRows()}</div>`,'leaders')}</div>`;}
function leaderDetail(){const l=S.leader,w=leaderWindow(l)||{},score=l?.analysis?.score||{};return `<div class="grid">${card(t('ПРОФИЛЬ ЛИДЕРА','LEADER PROFILE'),`${wallet(l.wallet)} ${badge(l.status)}<div class="balance">${num(N(score.score)!==null?score.score*100:null,0)} <small>LeaderScore</small></div><small>${esc(dt(l.last_seen))}</small>`,'leader-hero','hero')}${card(t('ПОКАЗАТЕЛИ','METRICS'),tabs(['30','90','180'],S.window,'window')+`<div class="metrics">${[['net_pnl','Чистый PnL','Net PnL'],['gross_profit','Валовая прибыль','Gross profit'],['gross_loss','Валовой убыток','Gross loss'],['trades','Сделки','Trades'],['profit_factor','Profit Factor','Profit Factor'],['win_rate','Доля побед','Win rate'],['expectancy','Ожидание','Expectancy'],['avg_win','Средняя прибыль','Average win'],['avg_loss','Средний убыток','Average loss'],['best','Лучшая сделка','Largest win'],['worst','Худшая сделка','Largest loss'],['max_drawdown','Просадка PnL (прокси)','PnL drawdown proxy']].map(([k,ru,en])=>metric(t(ru,en),esc(k==='win_rate'?num(w[k])+'%':num(w[k])))).join('')}</div><p class="footer-note">${esc(t('Просадка реализованного PnL не равна просадке капитала. Недоступные окна не заменяются другими.','Realized PnL drawdown is not account-equity drawdown. Unavailable windows are not substituted.'))}</p>`,'leader-metrics')}${card(t('КОМПОНЕНТЫ ОЦЕНКИ','SCORE COMPONENTS'),Object.entries(score).filter(([k])=>['profit_quality','consistency','drawdown_quality','sample_quality','recent_quality','anomaly'].includes(k)).map(([k,v])=>`<div class="state-row"><span>${esc(L(k))}</span><b>${num(v)}</b></div><div class="bar"><i style="width:${N(v)!==null?Math.max(0,Math.min(100,v*100)):0}%"></i></div>`).join('')+evidence(score.reasons||score.penalties)+`<p class="footer-note">${esc(t('LeaderScore не является вероятностью прибыли.','LeaderScore is not a profit probability.'))}</p>`,'score')}${card(t('ПОВЕДЕНИЕ','BEHAVIOR'),evidence(Object.fromEntries(Object.entries(w.deep_analysis||{}).filter(([k])=>/symbol|bias|leverage|sizing|consistency|recent/.test(k)))),'behavior')}</div>`;}
