 const cortex='M-3,-57 C-13,-70 -34,-65 -39,-52 C-56,-53 -69,-36 -64,-22 C-81,-9 -75,11 -65,18 C-71,36 -55,51 -40,49 C-34,67 -13,63 -3,48 Z';
