function agentCards(agents){return `<div class="list">${agentIds.map(id=>{const a=agents.find(a=>a.agent_id===id),out=a?.result;return `<button class="agent-row" data-agent="${id}" data-key="agent-${id}"><span class="grow"><strong>${esc(L(id))}</strong><small>${out?esc(out.instrument?.symbol+' · '+L(out.direction)+(a?.signal_status==='STALE'?' · '+t('архив','previous'):'')):esc(t('Нет актуального результата','No current result'))}</small></span><span class="right">${badge(a?.status)}<small>${out?pc(out.confidence):'—'}</small></span></button>`;}).join('')}</div>`;}
function agents(){const a=ai()?.agents||[],allowed=ai()?.allowed_instrument?.symbol,current=a.find(x=>x.result)?.result?.instrument?.symbol;return `<div class="button-row compact-links"><button data-nav="leaders">${icon('leaders')}${esc(t('Найденные лидеры','Discovered leaders'))}</button><button data-nav="activity">${esc(t('События','Activity'))}</button></div><div class="grid">${card(t('ЯДРО ИНТЕЛЛЕКТА','INTELLIGENCE CORE'),`<div class="row"><small>${num(ai()?.agent_summary?.available ?? a.filter(x=>['READY','ACTIVE','WAITING'].includes(x.status)).length,0)}/7 ${esc(t('доступны','available'))}</small>${current?`<small>${esc(current)}${allowed&&current!==allowed?' · '+esc(t('Исследование','Research')):''}</small>`:''}</div><small>${num(ai()?.agent_summary?.active ?? a.filter(x=>x.status==='ACTIVE').length,0)} ${esc(t('активны','active'))} · ${num(ai()?.agent_summary?.waiting ?? a.filter(x=>x.status==='WAITING').length,0)} ${esc(t('ожидают','waiting'))}</small><div class="agent-layout">${coreGraphic(a)}${agentCards(a)}</div>${allowed?`<div class="scope-strip">PAPER · ${esc(allowed)} ${esc(t('только','only'))}</div>`:''}`,'agent-network')}${card(t('КОНСЕНСУС','CONSENSUS'),consensus(),'agent-consensus')}</div>`;}

// Shared decorative component. Motion is not trading activity or authority.
function AtomAmbient(place='page'){return '<span class="atom-ambient atom-'+esc(place)+'" data-key="atom-'+esc(place)+'" aria-hidden="true"><svg viewBox="0 0 100 90" focusable="false"><g class="atom-ring atom-ring-a"><ellipse cx="50" cy="45" rx="39" ry="15"/><circle class="electron" cx="89" cy="45" r="2.3"/></g><g class="atom-ring atom-ring-b"><ellipse cx="50" cy="45" rx="39" ry="15"/><circle class="electron" cx="11" cy="45" r="2"/></g><g class="atom-ring atom-ring-c"><ellipse cx="50" cy="45" rx="39" ry="15"/><circle class="electron" cx="89" cy="45" r="1.8"/></g><circle class="atom-halo" cx="50" cy="45" r="14"/><circle class="atom-nucleus" cx="50" cy="45" r="4.2"/><circle class="atom-dust" cx="18" cy="22" r="1"/><circle class="atom-dust dust-b" cx="79" cy="70" r=".8"/></svg></span>';}
function operatorReview(m){const r=m.operator_review;if(!r)return '';return card(t('ПРОВЕРКА ОПЕРАТОРОМ','OPERATOR REVIEW'),'<div class="row">'+badge('BLOCKED')+'<span class="badge warn">⚠ '+esc(S.snapshot.scope.network)+'</span></div><p class="footer-note">'+esc(t('Историческая операция не разрешена. Новый session ID не снимает блокировку Risk. Старый ордер не будет повторён, резерв остаётся закрытым.','Historical execution remains unresolved. A new session ID cannot remove the Risk hold. The old order will not be retried; its reserve stays locked.'))+'</p><div class="metrics">'+metric(t('Исторических операций','Historical operations'),num(r.historical_count,0))+metric(t('Карантин','Quarantine'),cash(r.quarantined_reserve))+metric(t('Для новых операций','For new operations'),cash(r.available_for_new))+'</div><details><summary>'+esc(t('Результат проверки и технические детали','Review result and technical details'))+'</summary><p>'+esc(t('Арифметический остаток — НЕ разрешённый торговый капитал.','Arithmetic headroom is NOT authorized trading capital.'))+' '+cash(r.arithmetic_headroom)+'</p>'+evidence({review:r,historical:m.quarantine?.technical_details})+'</details>','operator-review');}

function manual(){const m=S.snapshot.manual_copy||{},a=S.snapshot.account?.portfolio,draft=S.manualDirty?S.manualDraft:null,editable=!m.selected_leader||S.manualEditing,blocked=!!m.quarantine?.operator_review_required||['PENDING','UNKNOWN','ERROR'].includes(m.ui_state||m.status),resume=!!m.selected_leader&&!m.enabled&&!!m.generation_id;return `${operatorReview(m)}${m.quarantine&&!m.operator_review?`<div class="notice"><strong>${esc(t('Ручное копирование приостановлено','Manual Copy paused'))}</strong><p>${esc(t('Исход одной предыдущей операции неизвестен. Автоматической повторной отправки не будет. Нужна проверка оператором.',m.quarantine.message))}</p>${esc(t('Резерв сохранён','Reservation held'))}: ${cash(m.quarantine.reservation_held)}<details><summary>${esc(t('Технические детали','Technical details'))}</summary><pre>${esc(JSON.stringify(m.quarantine.technical_details,null,2))}</pre></details></div>`:''}<div class="grid two manual-grid"><div class="grid">${card(t('ЛИДЕР И КОПИРОВАНИЕ','LEADER & COPY'),`<div class="row">${badge(m.ui_state||m.status)}${m.selected_leader?wallet(m.selected_leader):esc(t('Лидер не выбран','No leader selected'))}</div>${m.status==='HOLD'?`<p class="footer-note">${esc(t('Удерживаем существующие позиции','Holding existing positions'))}</p>`:''}<form id="manual-form"><div ${editable?'':'hidden'}><label for="manual-wallet">${esc(t('Адрес лидера','Leader address'))}</label><input id="manual-wallet" name="leader" autocomplete="off" spellcheck="false" required pattern="0x[0-9a-fA-F]{40}" value="${esc(draft?.leader??m.selected_leader??'')}" placeholder="0x…"></div>${m.selected_leader?`<button type="button" class="link" data-change-leader>${esc(t(editable?'Скрыть адрес':'Сменить лидера',editable?'Hide address':'Change leader'))}</button>`:''}<label for="allocation">${esc(t('Доля торгового капитала','Trading capital allocation'))}</label><div class="allocation-value"><output id="allocation-output">${num(draft?.allocation_pct??m.allocation_pct??m.configuration?.allocation_pct??1,0)}</output>%</div><input id="allocation" type="range" min="1" max="100" step="1" value="${draft?.allocation_pct??m.allocation_pct??m.configuration?.allocation_pct??1}"><div class="button-row"><button class="${m.selected_leader&&!editable?'secondary':'primary'}" type="submit" ${blocked?'disabled':''}>${esc(blocked?t('ТРЕБУЕТСЯ ПРОВЕРКА','REVIEW REQUIRED'):!m.selected_leader||editable?t('ДОБАВИТЬ КОШЕЛЁК','ADD WALLET'):t('Сохранить настройки','Save settings'))}</button>${m.selected_leader&&!m.enabled&&!editable?`<button class="primary" type="button" data-manual-start ${blocked?'disabled':''}>${esc(resume?t('ВОЗОБНОВИТЬ','RESUME COPYING'):t('НАЧАТЬ КОПИРОВАНИЕ','START COPY'))}</button>`:''}${m.enabled?`<button type="button" data-stop>${esc(t('Пауза','Pause'))}</button>`:''}</div><p id="manual-form-status" role="status" aria-live="polite"></p></form><details><summary>${esc(t('Как это работает','How it works'))}</summary><p class="footer-note">${esc(t('100% — доступный торговый капитал. Ручное копирование независимо от PAPER. Возможны реальные ордера. Пауза сохраняет позиции.','100% means allocatable trading capital. Manual Copy is independent of PAPER. Real orders are possible. Pause retains positions.'))} ${esc(S.snapshot.scope.network)}</p></details>${m.selected_leader?`<button class="link" data-manual-analysis="${esc(m.selected_leader)}">${esc(t('Анализ лидера →','Leader analysis →'))}</button>`:''}`,'manual-control')}${card(t('СКОПИРОВАННЫЕ ПОЗИЦИИ','COPIED POSITIONS'),(a?.completeness==='COMPLETE'?positionRows(M.positions(S.snapshot,'LIVE').filter(p=>p.origin==='MANUAL_LEADER_COPY')):empty()),'manual-positions')}</div><div class="grid">${card(t('КАПИТАЛ РУЧНОГО КОПИРОВАНИЯ','MANUAL COPY CAPITAL'),`<div class="eyebrow">${esc(t('Реальный счёт · не PAPER','Real account · not PAPER'))} · ${esc(S.snapshot.scope.network)}</div>${m.capital_status&&m.capital_status!=='FRESH'?`<p class="notice">${esc(t(m.capital_status==='STALE'?'Данные счёта устарели':'Данные счёта недоступны',m.capital_status==='STALE'?'ACCOUNT DATA STALE':'ACCOUNT DATA UNAVAILABLE'))}</p>`:''}<div class="balance compact">${cash(a?.equity)}</div><div class="metrics">${metric(t('Торговый капитал','Allocatable'),cash(m.allocatable_capital))}${metric(t('Доля','Allocation'),num(m.allocation_pct,0)+'%')}${metric(t('Лимит','Limit'),cash(m.allocation_limit))}${metric(t('Занято','Committed'),cash(m.committed))}${metric(t('Резерв','Reserved'),cash(m.reserved))}${metric(t('Карантин','Quarantine'),cash(m.quarantine?m.quarantined_reserve:0))}${metric(t('Для новых операций','For new operations'),cash(m.quarantine?m.available_for_new:m.available))}</div>`,'manual-capital','capital-glass')}${card(t('КАПИТАЛЬНАЯ БАЗА ЛИДЕРА','LEADER CAPITAL BASIS'),`<div class="metrics">${['','xyz'].map(k=>metric(k||t('Основной пул','Main pool'),cash(m.leader_capital_denominator?.[k]))).join('')}</div><small>${esc(dt(m.last_leader_evidence_ms))}</small><details><summary>${esc(t('О базе расчёта','About this basis'))}</summary><p class="footer-note">${esc(t('Капитал лидера по пулам — знаменатель пропорционального копирования, не баланс вашего счёта.','Leader equity per pool is the denominator for proportional copying, not your account balance.'))}</p>${evidence(m.denominator_evidence_type)}</details>`,'leader-capital')}${card(t('ИСПОЛНЕНИЕ','EXECUTION'),(S.snapshot.account?.actions||[]).filter(a=>a.origin==='MANUAL_LEADER_COPY'&&a.status!=='ARCHIVED_UNRESOLVED').slice(0,8).map(a=>`<div class="state-row"><div><b>${esc(a.intent?.instrument?.symbol)} · ${esc(L(a.intent?.action))}</b><small>${esc(dt(a.timestamp))}</small></div>${badge(a.status)}</div>`).join('')||empty(),'manual-activity')}${m.archived_operations?.length?`<details><summary>${esc(t('История · Архивные операции','History · Archived operations'))}</summary>${m.archived_operations.map(a=>`<p>${esc(t('Исторический исход неизвестен · Повтор запрещён','Historical outcome unknown · Retry prohibited'))}</p><details><summary>${esc(t('Технические детали','Technical details'))}</summary><pre>${esc(JSON.stringify(a,null,2))}</pre></details>`).join('')}</details>`:''}</div></div>`;}
function detail(){const p=S.position;if(!p)return empty();const timeline=M.timeline(p),duration=p.outcome?.duration_ms??(N(p.created_ms)!==null?Date.now()-p.created_ms:null);return `<div class="grid">${card(`${p.instrument?.symbol||'—'} · ${L(p.side)}`,`${badge(p.state)} <small>${esc(p.mode)} · ${esc(L(p.origin))}</small><div class="balance">${cash(p.pnl)}</div>${p.leader?wallet(typeof p.leader==='string'?p.leader:Object.keys(p.leader)[0]):''}`,'position-hero','hero')}<div class="split"><div class="grid">${card(t('РЫНОК И ИСПОЛНЕНИЕ','MARKET & EXECUTION'),`${tabs(['1m','5m','15m','1h','4h','1d'],S.interval,'interval')}<canvas class="chart candle" id="position-chart" data-key="position-canvas" role="img" aria-label="${esc(t('Свечи и подтверждённые исполнения','Candles and proven executions'))}"></canvas><div id="position-chart-tip" class="chart-tooltip"></div><small>${esc(t('Маркеры — только подтверждённые исполнения этой позиции.','Markers show proven fills for this position only.'))}</small>`,'candle')}${card(t('ПОЧЕМУ ЭТА СДЕЛКА?','WHY THIS TRADE?'),timeline.length?`<ol class="timeline">${timeline.map((x,i)=>`<li data-key="timeline-${i}"><small>${esc(dt(x.timestamp??x.created_ms))}</small><b>${esc(L(x.type||x.kind||x.stage))}</b>${evidence(x.state||x.status||x.reason||x.summary||x.evidence?.decision||x.evidence?.action)}<details><summary>${esc(t('Доказательства','Evidence'))}</summary>${evidence(x.data||x.evidence)}</details></li>`).join('')}</ol>`:empty(t('Причинная история недоступна. Происхождение не предполагается.','Causal history unavailable. Provenance is not assumed.')),'timeline')}</div><div class="grid">${card(t('ПАРАМЕТРЫ ПОЗИЦИИ','POSITION METRICS'),`<div class="metrics">${metric(t('Начальный вход','Initial entry'),cash(p.initial_entry_price??p.entry))}${metric(t('Средний вход','AVG entry'),cash(p.entry_price??p.entry))}${metric(t('Текущая цена','Current price'),cash(p.current_price))}${metric(t('Ликвидация','Liquidation'),cash(p.liquidation_price))}${metric(t('Маржа','Margin'),cash(p.margin))}${metric(t('Номинал','Notional'),cash(p.notional))}${metric(t('Плечо','Leverage'),esc(num(p.leverage,0)+'×'))}${metric(t('Объём','Size'),secret(num(p.size,6)))}${metric(t('Длительность','Duration'),N(duration)!==null?num(duration/3600000,1)+' '+t('ч','h'):'—')}${metric('ROE %',esc(p.outcome?.return_pct!=null?num(p.outcome.return_pct)+'%':N(p.pnl)!==null&&N(p.margin)>0?num(p.pnl/p.margin*100)+'%':'—'))}</div>`,'position-metrics')}${card(t('АНАЛИЗ ЭТОЙ ПОЗИЦИИ','THIS POSITION’S ANALYSIS'),positionAI(p),'position-ai')}</div></div></div>`;}
function positionAI(p){const analysis=(p.timeline||[]).filter(x=>x.type==='ANALYSIS').at(-1)?.evidence,decision=(p.timeline||[]).filter(x=>x.type==='CONSENSUS').at(-1)?.evidence;return Array.isArray(analysis)?consensus(decision||null)+fold(t('Семь агентов · подробности','Seven agents · details'),agentCards(analysis.map(result=>({agent_id:result.agent_id,result,status:Date.now()-result.created_ms<=120000?'ACTIVE':'DEGRADED'}))),'position-agents'):empty(t('Анализ, связанный с этой позицией, недоступен','Position-linked analysis unavailable'));}
function analytics(){const run=r(),a=run?.analytics||{},episodes=run?.episodes||[],start=episodes.map(p=>p.created_ms).filter(v=>N(v)!==null).sort((a,b)=>a-b)[0];return `<div class="grid">${sessionCard()}${card(t('РЕЗУЛЬТАТЫ СЕССИИ','SESSION PERFORMANCE'),`<div class="session">${esc(S.mode)} · ${esc(t('Первый наблюдаемый эпизод','First observed episode'))}: ${esc(dt(start))}</div>${chartBlock('analytics-chart')}`,'analytics-chart-card')}${card(t('ПОКАЗАТЕЛИ','METRICS'),`<div class="metrics">${Object.entries(a).filter(([k,v])=>N(v)!==null&&!['sample_size'].includes(k)).map(([k,v])=>metric(L(k),esc(k==='win_rate'?pc(v):num(v)))).join('')}</div><p class="footer-note">${esc(t('Последние 100 исходов. Просадка — прокси реализованного PnL, не капитала.','Latest 100 outcomes. Drawdown is a realized-PnL proxy, not equity drawdown.'))}</p>`,'analytics-metrics')}${card(t('КАЧЕСТВО РЕШЕНИЙ','DECISION QUALITY'),(run?.calibration||[]).slice(0,8).map(c=>`<div class="state-row"><span>${esc(c.mode)} · ${esc(t('Выборка','Sample'))} ${num(c.sample_count,0)}</span><b>${cash(c.net_pnl)}</b></div>`).join('')+`<p class="footer-note">${esc(t('Оценочные записи, не самоизменение стратегии. Уверенность не гарантирует прибыль.','Evaluation records, not self-modifying strategy. Confidence does not guarantee profit.'))}</p>`,'calibration')}</div>`;}
function apiBudgetCard(){const b=S.snapshot.health?.api_budget;if(!b||b.state==='UNKNOWN')return card('HYPERLIQUID API',esc(t('Метрики недоступны','Metrics unavailable')),'api-budget');const stale=Date.now()-b.checked_ms>15000;return card('HYPERLIQUID API',`<div class="row"><span>REST / min</span><b>${num(b.rest_weight_1m,0)} / ${num(b.rest_limit,0)}</b></div><div class="row"><span>${esc(t('Загрузка · оценка веса','Usage · estimated weight'))}</span><b>${num(100*b.rest_weight_1m/b.rest_limit,1)}%</b></div><div class="row"><span>${esc(t('Пик за окно до 24ч','Peak · retained window up to 24h'))}</span><b>${num(100*b.rest_weight_peak_1m/b.rest_limit,1)}%</b></div><div class="row"><span>WebSocket</span><b>${num(b.ws_connections,0)} / 10 · ${num(b.ws_subscriptions,0)} / 1000 subs</b></div><div class="row"><span>HTTP 429</span><b>${num(b.http_429,0)}</b></div><small>${esc(stale?t('Метрики устарели','Metrics stale'):b.state)} · ${esc(dt(b.checked_ms))}</small>`,'api-budget');}
function health(){const h=S.snapshot.health;return `<div class="system-banner ${cls(h.status)}">${icon('health')}<span>${esc(L(h.status))}</span></div>${fold(t('Нагрузка API и лимиты','API load and limits'),apiBudgetCard(),'api-diagnostics')}<div class="grid two health-grid">${[[t('ДАННЫЕ','DATA'),['public_data','private_account','database']],[t('ИНТЕЛЛЕКТ','INTELLIGENCE'),['discovery','deep_analysis','watchlist','leader_detection','agents','consensus']],[t('ТОРГОВЛЯ','TRADING'),['authorization','allocation','risk','execution','reconciliation']],[t('ПРОДУКТ','PRODUCT'),['events','telegram','web']]].map(([title,keys])=>card(title,keys.map(k=>{const c=h.components[k]||{};return `<details class="health-detail"><summary><span>${esc(L(k))}</span>${c.worker_active&&c.status==='DEGRADED'?badge('ACTIVE')+' · ':''}${badge(c.status)}</summary><small>${esc(t('Последний успех','Last success'))}: ${esc(dt(c.last_success_ms))}</small>${evidence({[t('Проверка','Heartbeat')]:dt(c.heartbeat_ms||c.ready_observed_ms),[t('Причина','Reason')]:c.reasons||c.error||c.status,[t('Последнее решение','Last decision')]:c.last_decision_reasons,[t('Обработка','Processing')]:c.processing_degradation,[t('Manual Copy MAINNET','Manual Copy MAINNET')]:c.manual_copy_mainnet})}</details>`;}).join(''),title)).join('')}</div>`;}
function settings(){return `<div class="grid two">${card(t('СЧЁТ И ОТОБРАЖЕНИЕ','ACCOUNT & DISPLAY'),`${wallet(S.snapshot.scope.account)}<div class="state-row"><span>${esc(t('Сеть','Network'))}</span><b>${esc(S.snapshot.scope.network)}</b></div>${(S.snapshot.runtimes||[]).map(x=>`<div class="state-row"><span>${esc(x.mode)}</span>${badge(x.runtime_mode||x.status)}</div>`).join('')}<p class="footer-note">${esc(t('Выбор вкладки меняет только отображение. LIVE AUTO выключен.','View selection changes presentation only. LIVE AUTO is disabled.'))}</p>`,'settings-account')}${notificationSettings()}${card(t('ОТОБРАЖЕНИЕ','DISPLAY'),`<div class="state-row"><span>${esc(t('Язык','Language'))}</span><button data-language>${S.lang.toUpperCase()}</button></div><div class="state-row"><span>${esc(t('Приватность','Privacy'))}</span><button data-privacy>${esc(S.privacy?t('Вкл','On'):t('Выкл','Off'))}</button></div><div class="state-row"><span>${esc(t('Анимация','Motion'))}</span><button data-motion>${esc(S.motion?t('Вкл','On'):t('Выкл','Off'))}</button></div><button data-pending>${esc(t('Подтверждения LIVE','LIVE confirmations'))}</button>`,'settings-display')}</div>`;}

// Keyed DOM reconciliation preserves form values, scroll, focus, details and canvases.
function morph(parent,html){const template=document.createElement('template');template.innerHTML=html;patch(parent,template.content);}
function patch(old,fresh){const children=[...fresh.childNodes];for(let i=0;i<children.length;i++){const n=children[i],key=n.nodeType===1?n.getAttribute('data-key'):null;let o=old.childNodes[i];if(key){const found=[...old.childNodes].find(c=>c.nodeType===1&&c.getAttribute('data-key')===key);if(found&&found!==o){old.insertBefore(found,o||null);o=found;}}if(!o){old.append(n.cloneNode(true));continue;}if(o.nodeType!==n.nodeType||o.nodeName!==n.nodeName||(key&&o.getAttribute('data-key')!==key)){o.replaceWith(n.cloneNode(true));continue;}if(n.nodeType===3){if(o.textContent!==n.textContent)o.textContent=n.textContent;continue;}if(n.nodeType!==1)continue;for(const a of [...o.attributes])if(!n.hasAttribute(a.name)&&!(o.tagName==='DETAILS'&&a.name==='open'))o.removeAttribute(a.name);for(const a of [...n.attributes])if(o.getAttribute(a.name)!==a.value&&!(S.manualDirty&&['INPUT','OUTPUT'].includes(o.tagName)&&['value'].includes(a.name)))o.setAttribute(a.name,a.value);if(o.tagName==='CANVAS')continue;if(S.manualDirty&&o.id==='allocation-output')continue;patch(o,n);}while(old.childNodes.length>children.length)old.lastChild.remove();}
function render(){document.documentElement.lang=S.lang;document.body.classList.toggle('privacy',S.privacy);document.body.dataset.motion=S.motion?'on':'off';const previous=$('workspace')?.scrollTop;const displayMode=S.page==='detail'?S.position?.mode:S.page==='manual'?'MANUAL COPY':S.mode==='LIVE'?'LIVE':r()?.runtime_mode||'UNKNOWN';const content=!S.snapshot?`<div class="skeleton"></div><p class="loading-text">${esc(S.error?t('Откройте приложение через Telegram. Подтверждённый счёт или сервис недоступен.','Open through Telegram. Verified account or service unavailable.'):t('Подключаем подтверждённые данные…','Connecting verified data…'))}</p>`:({home,positions,leaders,leader:leaderDetail,agents,manual,detail,analytics,health,settings,activity:activityPage}[S.page]||home)();
const selectedModes=(S.snapshot?.runtimes||[]).map(x=>x.mode);if(S.snapshot?.account)selectedModes.push('LIVE');
morph($('terminal'),`<header>${icon('core').replace('<svg','<svg class="mark"')}<div class="brand"><b>WALLET HUNTER</b><small>${esc((displayMode||'UNKNOWN').replace('_',' '))} · ${esc(L(S.connection))}</small></div><button data-language aria-label="${esc(t('Язык','Language'))}">${S.lang.toUpperCase()}</button><button data-privacy aria-pressed="${S.privacy}" aria-label="${esc(t('Скрыть личные данные','Hide private data'))}">${icon('privacy')}</button><button data-nav="settings" aria-label="${esc(L('settings'))}">${icon('settings')}</button></header><main id="workspace"><div class="topline atom-topline">${AtomAmbient(S.page)}<h1>${['detail','leader'].includes(S.page)?`<button data-back aria-label="${esc(t('Назад','Back'))}">${icon('back')}</button> `:''}${esc(L(S.page))}</h1>${selectedModes.length&&!['manual','detail','leader'].includes(S.page)?`<select id="view-mode" aria-label="${esc(t('Режим отображения','Display mode'))}">${selectedModes.map(m=>`<option value="${m}" ${S.mode===m?'selected':''}>${m.replace('_',' ')}</option>`).join('')}</select>`:''}</div><div class="notice">${S.error&&S.snapshot?esc(t('Данные сохранены. Соединение потеряно; свежесть не гарантирована.','Showing retained data. Connection lost; freshness is not guaranteed.')):S.snapshot?.health?.status==='UNHEALTHY'?esc(t('Критическая проблема исполнения/данных. Проверьте Систему.','Critical execution/data issue. Check System Health.')):''}</div><div class="page" data-key="page-${S.page}">${content}</div></main><nav class="nav" aria-label="${esc(t('Навигация','Navigation'))}">${['home','manual','agents','core'].map(k=>`<button data-${k==='core'?'hub':'nav'}="${k}" class="${k==='core'?'core-button':''}" ${S.page===k?'aria-current="page"':''}>${k==='core'?`<span class="reactor">${icon(k)}</span>`:icon(k)}<small>${esc(k==='core'?t('Ещё','More'):k==='agents'?'AI':k==='manual'?t('Копирование','Copy'):L(k))}</small></button>`).join('')}</nav>`);if(previous)$('workspace').scrollTop=previous;drawCharts();}
function navigate(page){S.page=page;render();window.scrollTo(0,0);if(page==='settings'&&!S.notificationPrefs)void loadNotifications();if(page==='home')void loadHomePosition(true);}
async function loadNotifications(){try{const data=await read('/api/product/notification-preferences');S.notificationPrefs=data.preferences;render();}catch{toast(t('Настройки уведомлений недоступны','Notification preferences unavailable'));}}
function showSheet(title,html,type='info'){if(!document.querySelector('dialog')){const d=document.createElement('dialog');d.id='sheet';document.body.append(d);d.addEventListener('close',()=>{S.sheet=null;d.remove();});}const d=$('sheet');S.sheet=type;d.innerHTML=`<div class="section-head atom-sheet">${AtomAmbient('sheet')}<h2>${esc(title)}</h2><button data-close aria-label="${esc(t('Закрыть','Close'))}">${icon('close')}</button></div><div>${html}</div>`;if(!d.open)d.showModal();}
function toast(message){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=message;document.body.append(e);setTimeout(()=>e.remove(),2500);}
const headers=()=>({'Content-Type':'application/json','x-telegram-init-data':window.Telegram?.WebApp?.initData||''});
async function read(url,options={}){const response=await fetch(url,{cache:'no-store',...options,headers:headers()});if(!response.ok){const error=new Error(`HTTP_${response.status}`);try{error.detail=(await response.json()).detail;}catch{}throw error;}return response.json();}
function clearManualCache(){for(const storage of [localStorage,sessionStorage]){for(let i=storage.length-1;i>=0;i--){const key=storage.key(i);if(/^(wh[_:. -]?manual|manual[_:. -]?copy)/i.test(key))storage.removeItem(key);}}S.manualDirty=false;S.manualDraft=null;S.manualRequest=null;S.manualEditing=false;}
function snapshot(s,{cached=false}={}){if(!s||s.version!=='product-v1'||!s.scope||s.live_auto!==false)throw new Error('INVALID_PRODUCT');if(S.snapshot&&M.scopeKey(S.snapshot.scope)!==M.scopeKey(s.scope)){S.manualDirty=false;S.manualDraft=null;S.manualRequest=null;S.events=[];S.cursor=0;S.position=null;S.homePositionId=null;S.homeCandles=[];S.homeMark=null;S.page='home';S.proposals=[];S.notificationPrefs=null;$('sheet')?.close();}if(s.manual_copy?.reset_epoch&&s.manual_copy.reset_epoch!==S.snapshot?.manual_copy?.reset_epoch){try{clearManualCache();}catch{S.manualDirty=false;S.manualDraft=null;}}S.snapshot=mergeSnapshot(s);S.snapshotCached=cached;S.snapshotSavedAt=cached?(S.snapshotSavedAt||Date.now()):Date.now();if(!cached)persistSnapshot(S.snapshot);if(!M.runtime(S.snapshot,S.mode)&&S.mode!=='LIVE')S.mode=S.snapshot.runtimes[0]?.mode||(S.snapshot.account?'LIVE':'UNKNOWN');if(S.position){const current=allPositions().find(p=>p.id===S.position.id);if(current){S.position={...S.position,...current};applyMark();}}S.error=false;render();if(S.page==='home')void loadHomePosition();if(!cached&&['LIVE','OBSERVE','PAPER_AUTO','SHADOW','LIVE_CONFIRM'].includes(S.position?.mode||S.mode))void refreshLiveMarks();}
let refreshPending=null,lastSnapshot=0;
async function refresh(){if(refreshPending)return refreshPending;refreshPending=read('/api/product').then(s=>{snapshot(s);lastSnapshot=Date.now();}).catch(()=>{S.error=true;S.snapshotCached=Boolean(S.snapshot);render();}).finally(()=>refreshPending=null);return refreshPending;}
function streamPayload(data){const previous=new Set(S.events.map(e=>e.id));if(data.reset_required)S.events=[];S.events=M.mergeEvents(S.events,data.events,data.reset_required);if(Number.isSafeInteger(data.cursor))S.cursor=data.cursor;if(data.snapshot){snapshot(data.snapshot);lastSnapshot=Date.now();}else{render();if((data.events?.length&&Date.now()-lastSnapshot>3000)||Date.now()-lastSnapshot>30000)void refresh();}for(const e of data.events||[]){if(previous.has(e.id)||document.hidden||Date.now()-e.timestamp>30000||Date.now()<e.timestamp)continue;pulse(document.querySelector(`[data-key="event-${CSS.escape(e.id)}"]`),'activity-arrival');if(['AGENT_UPDATED','CONSENSUS_UPDATED','POSITION_UPDATED','LEADER_PROMOTED'].includes(e.type))document.querySelectorAll('.atom-ambient').forEach(el=>pulse(el,'atom-accent'));if(e.type==='AGENT_UPDATED'){const rows=Array.isArray(e.data.evidence)?e.data.evidence:[e.data.evidence];for(const a of rows){if(!agentIds.includes(a?.agent_id))continue;document.querySelectorAll(`[data-agent-edge="${a.agent_id}"]`).forEach(el=>pulse(el,'active-edge'));document.querySelectorAll(`[data-agent="${a.agent_id}"]`).forEach(el=>pulse(el,'node-event'));}}if(['CONSENSUS_UPDATED','EXECUTION_UPDATED','AUTHORIZATION_REQUIRED'].includes(e.type))pulse(document.querySelector('.reactor'),'flash');if(e.type==='CONSENSUS_UPDATED')document.querySelectorAll('.core-ring').forEach(el=>pulse(el,'core-event'));if(e.type==='LEADER_PROMOTED')pulse(document.querySelector('[data-key="leaders"]'),'flash');if(e.type==='POSITION_UPDATED')pulse(document.querySelector('[data-key="home-positions"]'),'flash');if(e.type==='HEALTH_UPDATED'&&e.data?.status==='DEGRADED')pulse(document.querySelector('.system-banner'),'flash');if(e.type==='AUTHORIZATION_REQUIRED'&&e.data?.evidence?.outcome==='CONFIRMATION_REQUIRED')toast(t('Есть предложение LIVE — откройте подтверждения в Ядре','LIVE proposal available — open confirmations in AI Core'));} }
let stopped=false;
async function connect(){while(!stopped){if(document.hidden){await new Promise(resolve=>setTimeout(resolve,2000));continue;}const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),45000);try{S.connection='CONNECTED';const response=await fetch(`/api/product/events/stream?after=${S.cursor}`,{headers:headers(),cache:'no-store',signal:abort.signal});if(!response.ok||!response.body)throw new Error('STREAM');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>2000000)throw new Error('BUFFER_LIMIT');let end;while((end=buffer.indexOf('\n\n'))>=0){const message=buffer.slice(0,end).replaceAll('\r','');buffer=buffer.slice(end+2);const data=message.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trim()).join('\n');if(data)streamPayload(JSON.parse(data));}if(Date.now()-lastSnapshot>30000)void refresh();if(S.page==='detail'&&Date.now()-S.marketAt>15000&&!S.marketBusy){S.marketBusy=true;void loadCandles().finally(()=>S.marketBusy=false);}}}catch{S.connection='RECONNECTING';S.error=true;render();}finally{clearTimeout(timer);}await new Promise(resolve=>setTimeout(resolve,2000));}}
function markPosition(row,mark){if(!row||!mark||N(mark.price)===null||N(mark.time)===null)return false;const age=Date.now()-mark.time;if(age<0||age>30000)return false;row.current_price=mark.price;row.mark_timestamp=mark.time;if(N(row.entry_price??row.entry)!==null&&N(row.size)!==null&&['LONG','SHORT'].includes(row.side)){const entry=N(row.entry_price??row.entry);row.pnl=(mark.price-entry)*row.size*(row.side==='LONG'?1:-1);row.pnl_kind='UNREALIZED_MARK_EXCLUDES_FEES';}if(typeof S!=='undefined'&&S.page==='home'&&S.homePositionId){const home=allPositions().find(x=>x.id===S.homePositionId);if(home&&home.instrument?.symbol===row.instrument?.symbol&&home.instrument?.network===row.instrument?.network){updateCandleTail(S.homeCandles,mark);rememberHomeMarket(homeMarketKey(home),{mark:{price:mark.price,time:mark.time},markAt:Date.now(),candles:S.homeCandles});}}return true;}
function updateCandleTail(rows,mark){if(!Array.isArray(rows)||!rows.length||N(mark?.price)===null||N(mark?.time)===null)return false;const last=rows[rows.length-1];if(!last||mark.time<last.t||mark.time-last.t>86400000)return false;last.c=mark.price;last.h=Math.max(last.h,mark.price);last.l=Math.min(last.l,mark.price);return true;}
function applyMark(){const p=S.position,m=S.mark;if(!p||!M.isOpen(p)||!markPosition(p,m))return;const portfolio=S.snapshot?.account?.portfolio;if(portfolio?.positions){const match=portfolio.positions.find(row=>M.liveId(S.snapshot.scope,row)===p.id);if(match)markPosition(match,m);} }
function liveMarkGroups(){const homeRow=S.homePositionId?allPositions().find(row=>row.id===S.homePositionId):null;const targetMode=S.position?.mode||homeRow?.mode||S.mode;const rows=targetMode==='LIVE'?(S.snapshot?.account?.portfolio?.positions||[]):(M.runtime(S.snapshot,targetMode)?.episodes||[]);const groups=new Map();for(const row of rows){if(!M.isOpen(row))continue;const symbol=(row.instrument?.dex?row.instrument.dex+':':'')+row.instrument?.symbol;if(!symbol||!row.instrument?.network)continue;const key=`${row.instrument.network}|${symbol}`;if(!groups.has(key))groups.set(key,{network:row.instrument.network,symbol,dex:row.instrument.dex||'',rows:[]});groups.get(key).rows.push(row);}return [...groups.values()];}
async function refreshLiveMarks(force=false){if(S.liveMarksBusy)return;const homeRow=S.homePositionId?allPositions().find(row=>row.id===S.homePositionId):null;const targetMode=S.position?.mode||homeRow?.mode||S.mode;if(!S.snapshot||!['LIVE','OBSERVE','PAPER_AUTO','SHADOW','LIVE_CONFIRM'].includes(targetMode))return;if(!force&&Date.now()-S.liveMarksAt<10000)return;const groups=liveMarkGroups();if(!groups.length)return;S.liveMarksBusy=true;let changed=false;try{const results=await Promise.all(groups.map(async group=>{try{const data=await read(`/api/price?coin=${encodeURIComponent(group.symbol.replace(/^.*:/,''))}&dex=${encodeURIComponent(group.dex)}&network=${encodeURIComponent(group.network)}`);return {...group,mark:{price:data.price,time:data.time}};}catch{return null;}}));for(const result of results.filter(Boolean)){for(const row of result.rows)changed=markPosition(row,result.mark)||changed;const selected=S.position&&result.rows.find(row=>targetMode==='LIVE'?M.liveId(S.snapshot.scope,row)===S.position.id:row.episode_id===S.position.episode_id);if(selected){S.mark=result.mark;changed=markPosition(S.position,result.mark)||changed;}const homeSelected=S.page==='home'&&(S.homePositionId?result.rows.find(row=>(targetMode==='LIVE'?M.liveId(S.snapshot.scope,row):row.episode_id)===S.homePositionId):result.rows[0]);if(homeSelected){S.homeMark=result.mark;S.homeMarketAt=Date.now();changed=markPosition(homeSelected,result.mark)||changed;}}S.liveMarksAt=Date.now();if(changed){if(S.position)applyMark();render();}}finally{S.liveMarksBusy=false;}}
async function loadCandles(){const p=S.position;if(!p)return;const req=++S.request;try{const symbol=(p.instrument.dex?p.instrument.dex+':':'')+p.instrument.symbol;const data=await read(`/api/product/market/candles?coin=${encodeURIComponent(symbol)}&network=${p.instrument.network}&interval=${S.interval}&hours=${S.interval==='1d'?720:168}`);if(req!==S.request||S.position?.id!==p.id)return;if(M.scopeKey(data.scope)!==M.scopeKey(S.snapshot.scope)||data.coin!==symbol)throw new Error('MARKET_SCOPE');const rows=M.candles(data.candles);if(rows.length)S.candles=rows;S.mark=data.mark||S.mark;if(!S.mark){const fallback=await read(`/api/price?coin=${encodeURIComponent(p.instrument.symbol)}&dex=${encodeURIComponent(p.instrument.dex||'')}&network=${encodeURIComponent(p.instrument.network)}`);S.mark={price:fallback.price,time:fallback.time};}S.marketAt=Date.now();applyMark();render();}catch{if(req!==S.request)return;try{const dex=p.instrument.dex||'',coin=p.instrument.symbol;const data=await read(`/api/price?coin=${encodeURIComponent(coin)}&dex=${encodeURIComponent(dex)}&network=${encodeURIComponent(p.instrument.network)}`);if(req!==S.request||S.position?.id!==p.id)return;S.mark={price:data.price,time:data.time};S.marketAt=Date.now();applyMark();render();}catch{drawCharts();}}}
async function loadHomePosition(force=false){if(S.page!=='home'||S.homeMarketBusy)return;const p=allPositions().find(x=>x.id===S.homePositionId)||allPositions().find(M.isOpen);if(!p)return;S.homePositionId=p.id;const key=homeMarketKey(p),cached=homeMarketCache.get(key);if(cached){S.homeCandles=cached.candles||[];S.homeMark=cached.mark||null;S.homeMarketAt=Math.max(cached.candlesAt||0,cached.markAt||0);}if(!force&&S.homeMarketAt&&Date.now()-S.homeMarketAt<15000)return;S.homeMarketBusy=true;const symbol=(p.instrument?.dex?p.instrument.dex+':':'')+p.instrument?.symbol;try{const data=await read(`/api/product/market/candles?coin=${encodeURIComponent(symbol)}&network=${p.instrument.network}&interval=${S.interval}&hours=${S.interval==='1d'?720:168}`);if(M.scopeKey(data.scope)!==M.scopeKey(S.snapshot.scope)||data.coin!==symbol)throw new Error('MARKET_SCOPE');const rows=Array.isArray(data.candles)?M.candles(data.candles):[];if(rows.length){S.homeCandles=rows;rememberHomeMarket(key,{candles:rows,candlesAt:Date.now()});}if(data.mark){S.homeMark={price:data.mark.price,time:data.mark.time};rememberHomeMarket(key,{mark:S.homeMark,markAt:Date.now()});}if(!S.homeMark){const fallback=await read(`/api/price?coin=${encodeURIComponent(p.instrument.symbol)}&dex=${encodeURIComponent(p.instrument.dex||'')}&network=${encodeURIComponent(p.instrument.network)}`);S.homeMark={price:fallback.price,time:fallback.time};rememberHomeMarket(key,{mark:S.homeMark,markAt:Date.now()});}S.homeMarketAt=Date.now();markPosition(p,S.homeMark);render();}catch{try{const fallback=await read(`/api/price?coin=${encodeURIComponent(p.instrument.symbol)}&dex=${encodeURIComponent(p.instrument.dex||'')}&network=${encodeURIComponent(p.instrument.network)}`);S.homeMark={price:fallback.price,time:fallback.time};rememberHomeMarket(key,{mark:S.homeMark,markAt:Date.now()});S.homeMarketAt=Date.now();markPosition(p,S.homeMark);render();}catch{drawCharts();}}finally{S.homeMarketBusy=false;}}
function canvas(id){const el=$(id);if(!el)return null;const box=el.getBoundingClientRect(),scale=Math.min(window.devicePixelRatio||1,2);if(el.width!==Math.round(box.width*scale)||el.height!==Math.round(box.height*scale)){el.width=Math.round(box.width*scale);el.height=Math.round(box.height*scale);}const c=el.getContext('2d');c.setTransform(scale,0,0,scale,0,0);c.clearRect(0,0,box.width,box.height);return{el,c,w:box.width,h:box.height};}
function drawCharts(){for(const id of ['home-chart','analytics-chart']){const x=canvas(id);if(!x)continue;const rows=M.curve(r(),S.period,Date.now());drawSeries(x,rows,id);}const home=canvas('home-position-chart');if(home){const p=allPositions().find(x=>x.id===S.homePositionId)||allPositions().find(M.isOpen);if(p)drawCandlesData(home,p,S.homeCandles,S.homeMark,'home-position-chart-tip');}const x=canvas('position-chart');if(x)drawCandlesData(x,S.position,S.candles,S.mark,'position-chart-tip');}
function waiting(x){x.c.fillStyle='#91aab7';x.c.font='13px system-ui';x.c.textAlign='center';x.c.fillText(t('Недостаточно подтверждённой истории','Insufficient verified history'),x.w/2,x.h/2);}
function drawPositionFallback(x,p){
 const entry=N(p?.entry),mark=N(p?.current_price),values=[entry,mark].filter(v=>v!==null);
 if(!values.length){waiting(x);return;}
 const {c,w,h}=x,lo=Math.min(...values),hi=Math.max(...values),range=hi-lo||Math.max(Math.abs(hi)*.002,1),y=v=>25+(hi-v)/range*(h-60);
 c.strokeStyle='#19313d';c.lineWidth=1;c.beginPath();c.moveTo(18,h/2);c.lineTo(w-18,h/2);c.stroke();
 if(entry!==null){c.setLineDash([4,4]);c.strokeStyle='#65e8f5';c.beginPath();c.moveTo(18,y(entry));c.lineTo(w-18,y(entry));c.stroke();c.setLineDash([]);c.fillStyle='#65e8f5';c.font='11px system-ui';c.textAlign='left';c.fillText(t('Вход','ENTRY')+' '+num(entry),18,Math.max(14,y(entry)-6));}
 if(mark!==null){c.strokeStyle='#b7a2fa';c.lineWidth=2;c.beginPath();c.moveTo(18,y(mark));c.lineTo(w-18,y(mark));c.stroke();c.fillStyle='#b7a2fa';c.textAlign='right';c.fillText(t('Текущая цена','MARK')+' '+num(mark),w-18,Math.max(14,y(mark)-6));}
 c.fillStyle='#91aab7';c.font='12px system-ui';c.textAlign='center';c.fillText(t('Свечи временно недоступны · текущая отметка подтверждена отдельно','Candles temporarily unavailable · live mark shown separately'),w/2,h-10);
}
function drawSeries(x,rows,id){const {c,w,h,el}=x;if(rows.length<2){waiting(x);return;}const min=Math.min(...rows.map(p=>p.value)),max=Math.max(...rows.map(p=>p.value)),range=max-min||1,point=(p,i)=>[15+i/(rows.length-1)*(w-30),h-30-(p.value-min)/range*(h-60)];c.strokeStyle='#18323d';c.lineWidth=1;for(let i=1;i<4;i++){c.beginPath();c.moveTo(10,i*h/4);c.lineTo(w-10,i*h/4);c.stroke();}c.beginPath();rows.forEach((p,i)=>{const [a,b]=point(p,i);i?c.lineTo(a,b):c.moveTo(a,b);});c.strokeStyle='#65e8f5';c.lineWidth=2;c.stroke();c.lineTo(w-15,h-10);c.lineTo(15,h-10);c.closePath();const g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,'#65e8f540');g.addColorStop(1,'#65e8f500');c.fillStyle=g;c.fill();el.onpointermove=e=>{const i=Math.max(0,Math.min(rows.length-1,Math.round((e.offsetX-15)/(w-30)*(rows.length-1))));$(`${id}-tip`).textContent=S.privacy?'':`${dt(rows[i].time)} · ${money(rows[i].value)}`;};}
function drawCandlesData(x,p,candles,mark,tipId){if(!p)return;const rows=(candles||[]).slice(-100),{c,w,h,el}=x;if(!rows.length){drawPositionFallback(x,p);return;}const now=N(mark?.price)??N(p.current_price),avg=N(p.entry_price??p.entry),initial=N(p.initial_entry_price),liq=N(p.liquidation_price),lines=[{v:initial,label:t('ВХОД','ENTRY'),color:'#65e8f5'},{v:avg,label:t('AVG ENTRY','AVG ENTRY'),color:'#56d7e8'},{v:now,label:t('NOW','NOW'),color:'#b7a2fa'},{v:liq,label:t('LIQ','LIQ'),color:'#ff9f68'}].filter(l=>N(l.v)!==null),max=Math.max(...rows.map(c=>c.h),...(S.privacy?[]:lines.map(l=>l.v))),min=Math.min(...rows.map(c=>c.l),...(S.privacy?[]:lines.map(l=>l.v))),range=max-min||max*.01||1,y=v=>25+(max-v)/range*(h-60),step=(w-72)/rows.length;for(let i=0;i<4;i++){const v=min+range*i/3;c.strokeStyle='#19313d';c.beginPath();c.moveTo(0,y(v));c.lineTo(w-60,y(v));c.stroke();c.fillStyle='#91aab7';c.font='10px system-ui';c.textAlign='left';c.fillText(num(v,2),w-59,y(v)+3);}rows.forEach((a,i)=>{const xx=8+i*step;c.strokeStyle=c.fillStyle=a.c>=a.o?'#53e6b1':'#ff7d91';c.beginPath();c.moveTo(xx,y(a.h));c.lineTo(xx,y(a.l));c.stroke();c.fillRect(xx-step*.3,Math.min(y(a.o),y(a.c)),Math.max(1,step*.6),Math.max(1,Math.abs(y(a.o)-y(a.c))));});(S.privacy?[]:lines).forEach(l=>{c.setLineDash([4,4]);c.strokeStyle=l.color;c.beginPath();c.moveTo(0,y(l.v));c.lineTo(w-65,y(l.v));c.stroke();c.setLineDash([]);c.fillStyle=l.color;c.fillText(l.label,8,Math.max(12,y(l.v)-5));});(S.privacy?[]:M.markers(p)).filter(m=>m.time>=rows[0].t&&m.time<=rows.at(-1).t).forEach(m=>{const index=rows.reduce((best,row,j)=>Math.abs(row.t-m.time)<Math.abs(rows[best].t-m.time)?j:best,0);c.fillStyle='#ffc778';c.beginPath();c.arc(8+index*step,y(m.price),3,0,Math.PI*2);c.fill();});el.onpointermove=e=>{const i=Math.max(0,Math.min(rows.length-1,Math.floor((e.offsetX-8)/step))),a=rows[i],marks=S.privacy?[]:M.markers(p).filter(m=>Math.abs(m.time-a.t)<900000);const tip=$(tipId);if(tip)tip.textContent=`${dt(a.t)} · O ${num(a.o)} H ${num(a.h)} L ${num(a.l)} C ${num(a.c)} ${marks.map(m=>L(m.action)+' @ '+num(m.price)).join(' · ')}`;};}
function drawCandles(x){drawCandlesData(x,S.position,S.candles,S.mark,'position-chart-tip');}
async function pending(){try{const data=await read('/api/product/confirmations/pending');S.proposals=data.proposals||[];showSheet(t('ПОДТВЕРЖДЕНИЯ LIVE','LIVE CONFIRMATIONS'),S.proposals.map(p=>`<button class="position" data-proposal="${esc(p.id)}"><span class="grow"><strong>${esc(p.intent.instrument.symbol)} · ${esc(L(p.intent.side))}</strong><small>${esc(dt(p.intent.expires_ms))}</small></span>${badge(p.status)}</button>`).join('')||empty(t('Нет ожидающих предложений','No pending proposals')));}catch{toast(t('LIVE CONFIRM не настроен или недоступен','LIVE CONFIRM is not configured or unavailable'));}}
function proposalSheet(p){const i=p.intent,risk=p.risk;showSheet(t('ПОДТВЕРДИТЬ РЕАЛЬНОЕ ДЕЙСТВИЕ','CONFIRM REAL ACTION'),`<div class="notice">${esc(t('Это действие может отправить реальный ордер.','This action may submit a real order.'))}</div><p class="session">${esc(i.scope?.network)} · ${esc(i.execution_mode||'LIVE')}</p><h2>${esc(i.instrument.symbol)} · ${esc(L(i.action))} · ${esc(L(i.side))}</h2>${wallet(i.scope?.account)}<div class="metrics">${metric(t('Объём','Size'),secret(num(i.size,6)))}${metric(t('Плечо','Leverage'),num(i.leverage,0))}${metric(t('Лимит цены','Price limit'),cash(i.limit_price))}${metric(t('Одобрено Risk','Risk approved size'),secret(num(risk?.approved_size,6)))}${metric(t('Истекает','Expires'),`<span data-countdown="${i.expires_ms}">${esc(dt(i.expires_ms))}</span>`)}</div>${evidence(i.slippage)}${badge(risk?.outcome)}<p class="footer-note">${esc(t('Текущий Risk будет перепроверен при подтверждении.','Current risk is checked again on confirmation.'))}</p><div class="button-row"><button class="primary" data-confirm="${esc(p.id)}" ${M.proposalValid(p,Date.now())?'':'disabled'}>${esc(t('ПОДТВЕРДИТЬ','CONFIRM'))}</button><button class="danger" data-reject="${esc(p.id)}" ${M.proposalValid(p,Date.now())?'':'disabled'}>${esc(t('ОТКЛОНИТЬ','REJECT'))}</button></div>`,'proposal');}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-agent]');if(!b)return;try{
if(b.hasAttribute('data-language')){S.lang=S.lang==='ru'?'en':'ru';pref.set('wh_lang',S.lang);render();if(S.sheet)$('sheet')?.close();}
else if(b.hasAttribute('data-privacy')){S.privacy=!S.privacy;pref.set('wh_privacy',S.privacy?'on':'off');render();}
else if(b.hasAttribute('data-motion')){S.motion=!S.motion;pref.set('wh_motion',S.motion?'on':'off');render();}
else if(b.dataset.activityFilter){S.activityFilter=b.dataset.activityFilter;render();}
else if(b.hasAttribute('data-load-notifications'))await loadNotifications();
else if(b.dataset.notification){S.prefsBusy=true;render();try{const data=await read('/api/product/notification-preferences',{method:'PUT',body:JSON.stringify({[b.dataset.notification]:!S.notificationPrefs[b.dataset.notification]})});S.notificationPrefs=data.preferences;}finally{S.prefsBusy=false;render();}}
else if(b.dataset.nav){$('sheet')?.close();navigate(b.dataset.nav);}
else if(b.hasAttribute('data-back'))navigate(S.page==='leader'?'leaders':'positions');
else if(b.hasAttribute('data-hub'))showSheet(t('ЕЩЁ','MORE'),`<div class="hub">${['positions','leaders','activity','health','settings'].map(k=>`<button data-nav="${k}">${icon(k)}${esc(L(k))}</button>`).join('')}</div><button data-pending class="primary" style="margin-top:16px">${esc(t('Подтверждения LIVE','LIVE confirmations'))}</button>`);
else if(b.hasAttribute('data-close'))$('sheet')?.close();
else if(b.dataset.copy){if(!S.privacy){await navigator.clipboard.writeText(b.dataset.copy);toast(t('Скопировано','Copied'));}}
else if(b.dataset.homePosition){const next=allPositions().find(p=>p.id===b.dataset.homePosition);if(!next)return;S.homePositionId=next.id;const cached=homeMarketCache.get(homeMarketKey(next));S.homeCandles=cached?.candles||[];S.homeMark=cached?.mark||null;S.homeMarketAt=Math.max(cached?.candlesAt||0,cached?.markAt||0);render();void loadHomePosition(true);}
else if(b.dataset.position){const p=allPositions().find(p=>p.id===b.dataset.position);if(!p)return;S.position=p;S.candles=[];S.mark=null;navigate('detail');if(p.episode_id){const data=await read('/api/product/positions/'+encodeURIComponent(p.episode_id));if(S.position?.id===p.id){S.position={...data,id:p.id};render();}}void loadCandles();}
else if(b.dataset.leader){S.leader=await read('/api/product/leaders/'+encodeURIComponent(b.dataset.leader));navigate('leader');}
else if(b.dataset.agent){const linked=S.page==='detail'?(S.position?.timeline||[]).filter(x=>x.type==='ANALYSIS').at(-1)?.evidence:null;const a=Array.isArray(linked)?{result:linked.find(a=>a.agent_id===b.dataset.agent),status:'UNKNOWN'}:ai()?.agents?.find(a=>a.agent_id===b.dataset.agent);showSheet(L(b.dataset.agent),`${badge(a?.status)}<details><summary>${esc(t('Технические данные','Technical data'))}</summary>${evidence({heartbeat:dt(a?.heartbeat_ms),missing_inputs:a?.missing_inputs,last_error:a?.last_error||t('Нет зарегистрированной ошибки','No recorded error')})}</details>${a?.result?`<div class="consensus-value">${esc(L(a.result.direction))} ${pc(a.result.confidence)}</div>${evidence(a.result.evidence)}<details><summary>${esc(t('Условия отмены','Invalidation'))}</summary>${evidence(a.result.invalidation)}</details><p class="footer-note">${esc(dt(a.result.created_ms))} · ${esc(a.signal_status||a.result.freshness)} · ${esc(a.result.feature_version)} / ${esc(a.result.strategy_version)}</p>`:empty()}`);}
else if(b.dataset.period){S.period=b.dataset.period;render();}else if(b.dataset.filter){S.filter=b.dataset.filter;render();}else if(b.dataset.window){S.window=b.dataset.window;render();}else if(b.dataset.interval){S.interval=b.dataset.interval;render();void loadCandles();}
else if(b.hasAttribute('data-pending'))await pending();else if(b.dataset.proposal){const p=S.proposals.find(p=>p.id===b.dataset.proposal);if(p)proposalSheet(p);}
else if(b.dataset.confirm||b.dataset.reject){const id=b.dataset.confirm||b.dataset.reject,p=S.proposals.find(p=>p.id===id);if(!M.proposalValid(p,Date.now()))return;document.querySelectorAll('[data-confirm],[data-reject]').forEach(x=>x.disabled=true);await read(`/api/product/confirmations/${encodeURIComponent(id)}/${b.dataset.confirm?'approve':'reject'}`,{method:'POST',body:JSON.stringify({proposal_hash:p.proposal_hash})});$('sheet')?.close();await refresh();}
else if(b.hasAttribute('data-change-leader')){S.manualEditing=!S.manualEditing;render();}
else if(b.hasAttribute('data-manual-start'))manualConfirm('start');
else if(b.dataset.manualAnalysis){const leader=b.dataset.manualAnalysis;showSheet(t('Анализ лидера','Leader analysis'),`<section id="manual-analysis" data-wallet="${esc(leader.toLowerCase())}">${empty(t('Загрузка анализа…','Loading analysis…'))}</section>`,'manual-analysis');await loadManualAnalysis(leader);}
else if(b.hasAttribute('data-stop'))manualConfirm('stop');else if(b.dataset.manualAction)await saveManual(b.dataset.manualAction);
}catch{toast(t('Действие недоступно. Обновите данные перед повторным действием.','Action unavailable. Refresh evidence before another action.'));}});
